int main(int argc, char **argv)
{
	const char *bdf = "0000:02:00.0";
	char p[256]; int fd, i, dry = 0;
	volatile uint32_t *M = NULL;

	for (i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-n")) dry = 1; else bdf = argv[i];
	}
	if (!dry) {
		snprintf(p, sizeof p, "/sys/bus/pci/devices/%s/resource0", bdf);
		fd = open(p, O_RDWR | O_SYNC);
		if (fd < 0) { perror("open"); return 1; }
		M = mmap(NULL, 32u*1024*1024, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
		if (M == MAP_FAILED) { perror("mmap"); return 1; }
	}
	for (i = 0; i < (int)(sizeof S / sizeof S[0]); i++) {
		if (dry) printf("%08x %08x\n", S[i][0], S[i][1]);
		else { M[S[i][0]] = S[i][1]; __sync_synchronize(); }
	}
	if (!dry) printf("fm6000_mgmt2pre: %d pre-loop writes\n", (int)(sizeof S / sizeof S[0]));
	return 0;
}
